<h1><?= e($title) ?></h1><?php errorSummary($errors); ?><form class="panel filters" method="post" action="<?= e(url('admin/' . $kind)) ?>"><?= csrf() ?><?php input('name', $data, 'Nombre del nuevo elemento'); ?><button class="button">Crear <?= $kind === 'categorias' ? 'categoría' : 'etiqueta' ?></button></form><p>Editar conserva la URL existente. Las eliminaciones de catálogos se confirman y son definitivas; las categorías con noticias requieren reasignación.</p><div class="catalog-grid"><?php foreach ($items as $item): ?><section class="panel"><h2><?= e($item['name']) ?></h2><form method="post" action="<?= e(url('admin/' . $kind)) ?>"><?= csrf() ?><input type="hidden" name="id" value="<?= e($item['id']) ?>"><div class="field"><label for="name-<?= e($item['id']) ?>">Nombre (obligatorio)</label><input id="name-<?= e($item['id']) ?>" name="name" value="<?= e($item['name']) ?>" maxlength="80" required></div><button class="button button--quiet">Guardar nombre<span class="sr-only"> <?= e($item['name']) ?></span></button></form><form method="post" action="<?= e(url('admin/' . $kind . '/' . $item['id'] . '/eliminar')) ?>" data-confirm><?= csrf() ?><?php if ($kind === 'categorias'): ?><div class="field"><label for="replacement-<?= e($item['id']) ?>">Reasignar noticias a</label><select id="replacement-<?= e($item['id']) ?>" name="replacement"><option value="">Sin reasignar (solo si está vacía)</option><?php foreach ($items as $other): ?><?php if ($other['id'] !== $item['id']): ?><option value="<?= e($other['id']) ?>"><?= e($other['name']) ?></option><?php endif; ?><?php endforeach; ?></select></div><?php endif; ?><label class="check"><input name="confirm" type="checkbox" value="1" required> Confirmo eliminar <?= e($item['name']) ?></label><button class="button button--danger">Eliminar<span class="sr-only"> <?= e($item['name']) ?></span></button></form></section><?php endforeach; ?></div>
